import{_ as i,o as a,c as e,ak as d}from"./chunks/framework.DvrM7GBU.js";const n=JSON.parse('{"title":"OCR资料导航","description":"","frontmatter":{},"headers":[],"relativePath":"OCR资料/OCR资料导航.md","filePath":"OCR资料/OCR资料导航.md","lastUpdated":1777977084000}'),o={name:"OCR资料/OCR资料导航.md"};function c(r,l,h,C,O,R){return a(),e("div",null,[...l[0]||(l[0]=[d('<h1 id="ocr资料导航" tabindex="-1">OCR资料导航 <a class="header-anchor" href="#ocr资料导航" aria-label="Permalink to “OCR资料导航”">​</a></h1><ul><li>分类：OCR / 证据链</li><li>子系统：OCR入口 / 映射表 / 证据回链</li><li>关键词标签：OCR、证据、映射、回查、原图、文本</li><li>来源类型：OCR 工程文档 / 证据回链说明</li><li>证据等级：已确认</li><li>完整度状态：已整理</li><li>版本号：4.x 系列通用</li><li>来源文件：<code>docs/OCR资料/OCR 资料总览与完整化现状.md</code></li><li>最后更新：2026-05-05</li><li>适合查询：OCR 证据链如何使用、如何查回原图、如何理解映射表</li></ul><p>一句话摘要：这是一份给普通玩家、维护者、研究者和 AI 检索系统看的 OCR 总入口，帮助你快速理解“原图、OCR 文本、映射表、专题文档”之间的关系，并按正确路径查证。</p><ul><li>适合对象：维护者、研究者、需要查证据的玩家、AI 检索系统</li><li>当前状态：已整理，可作为 OCR 入口首页</li><li>可信度：<code>[已确认]</code></li><li>推荐用途：查入口、看结构、学怎么回查证据、找到下一跳文档</li><li>关联文档： <ul><li><code>docs/OCR资料/OCR 资料总览与完整化现状.md</code></li><li><code>docs/OCR资料/OCR 完整化总表.md</code></li><li><code>docs/OCR资料/映射表/OCR 图片编号映射表.md</code></li><li><code>docs/OCR资料/OCR 状态词与回链规范.md</code></li><li><code>docs/OCR资料/OCR 证据链说明.md</code></li><li><code>docs/OCR资料/OCR 证据使用规范.md</code></li><li><code>docs/OCR资料/OCR 专题回链示例.md</code></li><li><code>docs/OCR资料/OCR 未识别与残缺清单.md</code></li></ul></li></ul><h2 id="快速目录" tabindex="-1">快速目录 <a class="header-anchor" href="#快速目录" aria-label="Permalink to “快速目录”">​</a></h2><ol><li><a href="#ocr-在资料库里是干什么的">OCR 在资料库里是干什么的</a></li><li><a href="#推荐阅读顺序">推荐阅读顺序</a></li><li><a href="#三类-ocr-原文入口">三类 OCR 原文入口</a></li><li><a href="#映射表怎么理解">映射表怎么理解</a></li><li><a href="#推荐查证路径">推荐查证路径</a></li><li><a href="#ocr-层当前在推进什么">OCR 层当前在推进什么</a></li><li><a href="#为什么普通玩家也值得看-ocr">为什么普通玩家也值得看 OCR</a></li><li><a href="#常见误区">常见误区</a></li><li><a href="#一句话使用建议">一句话使用建议</a></li></ol><h2 id="ocr-在资料库里是干什么的" tabindex="-1">OCR 在资料库里是干什么的 <a class="header-anchor" href="#ocr-在资料库里是干什么的" aria-label="Permalink to “OCR 在资料库里是干什么的”">​</a></h2><p>OCR 是“光学字符识别（Optical Character Recognition）”的简称。 在这个资料库里，OCR 文档的作用不是简单堆截图文字，而是把原始截图中的内容尽量变成：</p><ul><li>可检索</li><li>可引用</li><li>可回查</li><li>可作为专题研究的证据底层</li></ul><p>简单说：</p><ul><li>原始截图：证据源</li><li>OCR 文档：可检索文本层</li><li>映射表：编号追踪层</li><li>专题文档：归纳研究层</li></ul><h2 id="推荐阅读顺序" tabindex="-1">推荐阅读顺序 <a class="header-anchor" href="#推荐阅读顺序" aria-label="Permalink to “推荐阅读顺序”">​</a></h2><p>如果你是第一次进这个目录，建议按下面顺序读：</p><ol><li><code>docs/OCR资料/OCR 资料总览与完整化现状.md</code></li><li><code>docs/OCR资料/OCR 完整化总表.md</code></li><li><code>docs/OCR资料/映射表/OCR 图片编号映射表.md</code></li><li><code>docs/OCR资料/OCR 状态词与回链规范.md</code></li><li><code>docs/OCR资料/OCR 证据链说明.md</code></li><li><code>docs/OCR资料/OCR 证据使用规范.md</code></li><li><code>docs/OCR资料/OCR 专题回链示例.md</code></li><li><code>docs/OCR资料/OCR 未识别与残缺清单.md</code></li></ol><h2 id="三类-ocr-原文入口" tabindex="-1">三类 OCR 原文入口 <a class="header-anchor" href="#三类-ocr-原文入口" aria-label="Permalink to “三类 OCR 原文入口”">​</a></h2><h3 id="_1-脚本界面-ocr" tabindex="-1">1. 脚本界面 OCR <a class="header-anchor" href="#_1-脚本界面-ocr" aria-label="Permalink to “1. 脚本界面 OCR”">​</a></h3><ul><li><code>docs/OCR资料/基础写脚本界面截图转文本.md</code></li><li>用途：查脚本界面、积木、组件、作用域、指令、参数、触发时机等原始线索</li></ul><h3 id="_2-官方教程-ocr" tabindex="-1">2. 官方教程 OCR <a class="header-anchor" href="#_2-官方教程-ocr" aria-label="Permalink to “2. 官方教程 OCR”">​</a></h3><ul><li><code>docs/OCR资料/官方教程截图转文本索引.md</code></li><li>用途：查官方教程中广播、素材、组件、UI、系统说明等原始线索</li></ul><h3 id="_3-引擎更新-ocr" tabindex="-1">3. 引擎更新 OCR <a class="header-anchor" href="#_3-引擎更新-ocr" aria-label="Permalink to “3. 引擎更新 OCR”">​</a></h3><ul><li><code>docs/OCR资料/引擎更新截图转文本.md</code></li><li>用途：查版本更新、功能新增、联机 UI 演进、数据类型升级等原始线索</li></ul><h2 id="映射表怎么理解" tabindex="-1">映射表怎么理解 <a class="header-anchor" href="#映射表怎么理解" aria-label="Permalink to “映射表怎么理解”">​</a></h2><p><code>docs/OCR资料/映射表/OCR 图片编号映射表.md</code> 的作用，是把：</p><ul><li>原始图片编号</li><li>当前状态</li><li>对应 OCR 文档</li><li>对应专题文档</li></ul><p>串成一条可追溯链。</p><p>也就是说，你在专题里看到某个结论，如果想查它到底有没有证据、证据来自哪，就应该尽量回到对应编号。</p><h2 id="推荐查证路径" tabindex="-1">推荐查证路径 <a class="header-anchor" href="#推荐查证路径" aria-label="Permalink to “推荐查证路径”">​</a></h2><p>如果你想确认某条结论靠不靠谱，建议按这个顺序：</p><ol><li>先看专题文档里的结论。</li><li>看结论有没有给出截图编号、OCR 文档或映射表回链。</li><li>如果存在编号，就回到 <code>docs/OCR资料/映射表/OCR 图片编号映射表.md</code> 查原始对应关系。</li><li>再回到具体 OCR 转写文档核对原文。</li><li>如果 OCR 本身噪声很重，再回看原图或相邻页判断上下文。</li></ol><p>这样做的好处是：</p><ul><li>不容易把推断当成事实</li><li>能区分“截图明确写过”和“作者基于多份材料归纳出来”的区别</li><li>能快速发现某条结论是否还停留在待复核状态</li></ul><h2 id="ocr-层当前在推进什么" tabindex="-1">OCR 层当前在推进什么 <a class="header-anchor" href="#ocr-层当前在推进什么" aria-label="Permalink to “OCR 层当前在推进什么”">​</a></h2><p>当前主要推进方向：</p><ul><li>补齐尚未完整转写的截图材料</li><li>给更多专题文档补上 OCR 回链</li><li>统一“编号 → OCR 文本 → 专题结论”的三段式表达</li><li>把未识别、残缺、重复、待复核页分层整理</li><li>逐步把 OCR 层做成更适合网页端展开的证据附录区</li></ul><h2 id="为什么普通玩家也值得看-ocr" tabindex="-1">为什么普通玩家也值得看 OCR <a class="header-anchor" href="#为什么普通玩家也值得看-ocr" aria-label="Permalink to “为什么普通玩家也值得看 OCR”">​</a></h2><ul><li><code>[已确认]</code> 很多专题结论不是拍脑袋写出来的，而是从截图原文中提炼的</li><li><code>[已确认]</code> 当你发现某条结论不确定时，OCR 层就是最好的反查入口</li><li><code>[高可信推断]</code> 对后续网页端来说，OCR 层可以成为“证据展开区”，增强说服力</li></ul><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to “常见误区”">​</a></h2><h3 id="误区-1-ocr-文档只是原文堆砌-没有价值" tabindex="-1">误区 1：OCR 文档只是原文堆砌，没有价值 <a class="header-anchor" href="#误区-1-ocr-文档只是原文堆砌-没有价值" aria-label="Permalink to “误区 1：OCR 文档只是原文堆砌，没有价值”">​</a></h3><ul><li>实际上它是整个证据链的底层</li></ul><h3 id="误区-2-只看专题结论-不做原文回查" tabindex="-1">误区 2：只看专题结论，不做原文回查 <a class="header-anchor" href="#误区-2-只看专题结论-不做原文回查" aria-label="Permalink to “误区 2：只看专题结论，不做原文回查”">​</a></h3><ul><li>这样容易忽略版本差异、上下文限制和 OCR 错字影响</li></ul><h3 id="误区-3-把-ocr-文本里的错字直接当成真实术语" tabindex="-1">误区 3：把 OCR 文本里的错字直接当成真实术语 <a class="header-anchor" href="#误区-3-把-ocr-文本里的错字直接当成真实术语" aria-label="Permalink to “误区 3：把 OCR 文本里的错字直接当成真实术语”">​</a></h3><ul><li>OCR 有识别误差，必要时要回看截图和相邻页语境</li></ul><h3 id="误区-4-觉得-无有效文本-就等于-这页没价值" tabindex="-1">误区 4：觉得“无有效文本”就等于“这页没价值” <a class="header-anchor" href="#误区-4-觉得-无有效文本-就等于-这页没价值" aria-label="Permalink to “误区 4：觉得“无有效文本”就等于“这页没价值””">​</a></h3><ul><li>不一定。有些页虽然 OCR 读不出来，但仍可能是转场页、纯图示页或主题邻接页</li></ul><h2 id="一句话使用建议" tabindex="-1">一句话使用建议 <a class="header-anchor" href="#一句话使用建议" aria-label="Permalink to “一句话使用建议”">​</a></h2><p>如果你只是想找答案，看专题；如果你想确认答案靠不靠谱，就顺着“专题 → 映射表 → OCR 原文 → 原图”往回查。</p>',47)])])}const t=i(o,[["render",c]]);export{n as __pageData,t as default};
